    </button>

    @if (_expanded)
    {
        <div class="panel-body">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="_currentPassword" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="_newPassword" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm New Password</label>
                <input id="confirmPassword" type="password" @bind="_confirmPassword" />
            </div>

            @if (_validationError is not null)
            {
                <div class="toast error">⚠️ @_validationError</div>
            }

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@_saving">
                    @(_saving ? "Updating..." : "Update Password")
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">✅ Password updated successfully!</div>
            }
            @if (_errorMessage is not null)
            {
                <div class="toast error">❌ @_errorMessage</div>
            }
        </div>
    }
</div>

@code {
    private bool _expanded;
    private bool _saving;
    private bool _showSuccess;
    private string? _errorMessage;
    private string? _validationError;

    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";

    private async Task UpdatePassword()
    {
        _validationError = null;
        _errorMessage = null;
        _showSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _validationError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _validationError = "New password is required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _validationError = "New password and confirmation do not match.";
            return;
        }

        _saving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _showSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}

