            await SettingsService.SaveProfileAsync(updated);
            _savedProfile = updated;
            _showSuccess = true;
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }

    private void DiscardChanges()
    {
        ApplySavedValues();
        _showSuccess = false;
        _errorMessage = null;
    }
}

