@inject ISettingsService SettingsService

<div class="settings-section appearance-section">
    <h2>Appearance Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-form">
            <div class="form-group">
                <h3>Theme</h3>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Light"
                               checked="@(_theme == "Light")"
                               @onchange="@(() => _theme = "Light")" />
                        <span>☀️ Light</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Dark"
                               checked="@(_theme == "Dark")"
                               @onchange="@(() => _theme = "Dark")" />
                        <span>🌙 Dark</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="System"
                               checked="@(_theme == "System")"
                               @onchange="@(() => _theme = "System")" />
                        <span>💻 System</span>
                    </label>
                </div>
            </div>

            <div class="form-group">
                <h3>Font Size</h3>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Small"
                               checked="@(_fontSize == "Small")"
                               @onchange="@(() => _fontSize = "Small")" />
                        <span>Small</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Medium"
                               checked="@(_fontSize == "Medium")"
                               @onchange="@(() => _fontSize = "Medium")" />
                        <span>Medium</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Large"
                               checked="@(_fontSize == "Large")"
                               @onchange="@(() => _fontSize = "Large")" />
                        <span>Large</span>
                    </label>
                </div>
            </div>

            <div class="form-group">
                <h3>Language</h3>
                <select @bind="_language" class="form-select">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <div class="form-group">
                <label class="toggle-item">
                    <span>Compact Mode</span>
                    <input type="checkbox" @bind="_compactMode" />
                    <span class="toggle-switch"></span>
                </label>
            </div>

            <div class="live-preview" style="@GetPreviewStyle()">
                <h4>Live Preview</h4>
                <p>This is how your content will look with the selected settings.</p>
                <p>The quick brown fox jumps over the lazy dog.</p>
                <button class="btn btn-primary preview-btn">Sample Button</button>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save")
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">✅ Appearance settings saved!</div>
            }
            @if (_errorMessage is not null)
            {
                <div class="toast error">❌ @_errorMessage</div>
            }
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;
    private string? _errorMessage;

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewStyle()
    {
        var bg = _theme switch
        {
            "Light" => "background-color: #ffffff; color: #1a1a1a;",
            "Dark" => "background-color: #1a1a2e; color: #e0e0e0;",
            _ => "background-color: #f5f5f5; color: #333333;"
        };

        var font = _fontSize switch
        {
            "Small" => "font-size: 0.85rem;",
            "Large" => "font-size: 1.25rem;",
            _ => "font-size: 1rem;"
        };

        var padding = _compactMode ? "padding: 0.5rem;" : "padding: 1.5rem;";

        return $"{bg} {font} {padding} border-radius: 8px; border: 1px solid #ddd; margin: 1rem 0;";
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        _showSuccess = false;
        _errorMessage = null;

        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _showSuccess = true;
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}

@page "/settings"
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-page">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="SetSection" />

    <div class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetSection(string section)
    {
        _activeSection = section;
    }
}

arguments.file_text:
.settings-page {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-nav {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    padding: 0 0.75rem;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    border: none;
    background: transparent;
    border-radius: 8px;
    cursor: pointer;
    font-size: 0.95rem;
    color: #555;
    transition: all 0.2s ease;
    text-align: left;
    width: 100%;
}

.settings-nav-item:hover {
    background: #e9ecef;
    color: #333;
}

.settings-nav-item.active {
    background: #0d6efd;
    color: #fff;
    font-weight: 500;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Content Area */
.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
    color: #1a1a1a;
}

.settings-section h3 {
    margin: 1.5rem 0 0.75rem;
    font-size: 1.1rem;
    font-weight: 500;
    color: #333;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #444;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="url"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #d0d0d0;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.1);
}

.form-select {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #d0d0d0;
    border-radius: 6px;
    font-size: 0.95rem;
    background: #fff;
}

/* Buttons */
.btn {
    padding: 0.6rem 1.2rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-secondary {
    background: #6c757d;
    color: #fff;
}

.btn-secondary:hover:not(:disabled) {
    background: #5c636a;
}

.btn-danger {
    background: #dc3545;
    color: #fff;
}

.btn-danger:hover:not(:disabled) {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Toast Messages */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
    animation: slideIn 0.3s ease;
}

.toast.success {
